     1→import {byteArrayEquals} from "@chainsafe/ssz";
     2→import {ForkName, ForkSeq, isForkPostDeneb} from "@lodestar/params";
     3→import {BeaconBlockBody, BlindedBeaconBlockBody, deneb, isExecutionPayload} from "@lodestar/types";
     4→import {toHex, toRootHex} from "@lodestar/utils";
     5→import {CachedBeaconStateBellatrix, CachedBeaconStateCapella} from "../types.js";
     6→import {
     7→  executionPayloadToPayloadHeader,
     8→  getFullOrBlindedPayloadFromBody,
     9→  isMergeTransitionComplete,
    10→} from "../util/execution.js";
    11→import {computeEpochAtSlot, getRandaoMix} from "../util/index.js";
    12→import {BlockExternalData, ExecutionPayloadStatus} from "./externalData.js";
    13→
    14→export function processExecutionPayload(
    15→  fork: ForkSeq,
    16→  state: CachedBeaconStateBellatrix | CachedBeaconStateCapella,
    17→  body: BeaconBlockBody | BlindedBeaconBlockBody,
    18→  externalData: Omit<BlockExternalData, "dataAvailabilityStatus">
    19→): void {
    20→  const payload = getFullOrBlindedPayloadFromBody(body);
    21→  const forkName = ForkName[ForkSeq[fork] as ForkName];
    22→  // Verify consistency of the parent hash, block number, base fee per gas and gas limit
    23→  // with respect to the previous execution payload header
    24→  if (isMergeTransitionComplete(state)) {
    25→    const {latestExecutionPayloadHeader} = state;
    26→    if (!byteArrayEquals(payload.parentHash, latestExecutionPayloadHeader.blockHash)) {
    27→      throw Error(
    28→        `Invalid execution payload parentHash ${toRootHex(payload.parentHash)} latest blockHash ${toRootHex(
    29→          latestExecutionPayloadHeader.blockHash
    30→        )}`
    31→      );
    32→    }
    33→  }
    34→
    35→  // Verify random
    36→  const expectedRandom = getRandaoMix(state, state.epochCtx.epoch);
    37→  if (!byteArrayEquals(payload.prevRandao, expectedRandom)) {
    38→    throw Error(`Invalid execution payload random ${toHex(payload.prevRandao)} expected=${toHex(expectedRandom)}`);
    39→  }
    40→
    41→  // Verify timestamp
    42→  //
    43→  // Note: inlined function in if statement
    44→  // def compute_timestamp_at_slot(state: BeaconState, slot: Slot) -> uint64:
    45→  //   slots_since_genesis = slot - GENESIS_SLOT
    46→  //   return uint64(state.genesis_time + slots_since_genesis * SECONDS_PER_SLOT)
    47→  if (payload.timestamp !== state.genesisTime + state.slot * state.config.SECONDS_PER_SLOT) {
    48→    throw Error(`Invalid timestamp ${payload.timestamp} genesisTime=${state.genesisTime} slot=${state.slot}`);
    49→  }
    50→
    51→  if (isForkPostDeneb(forkName)) {
    52→    const maxBlobsPerBlock = state.config.getMaxBlobsPerBlock(computeEpochAtSlot(state.slot));
    53→    const blobKzgCommitmentsLen = (body as deneb.BeaconBlockBody).blobKzgCommitments?.length ?? 0;
    54→    if (blobKzgCommitmentsLen > maxBlobsPerBlock) {
    55→      throw Error(`blobKzgCommitmentsLen of ${blobKzgCommitmentsLen} exceeds limit=${maxBlobsPerBlock}`);
    56→    }
    57→  }
    58→
    59→  // Verify the execution payload is valid
    60→  //
    61→  // if executionEngine is null, executionEngine.onPayload MUST be called after running processBlock to get the
    62→  // correct randao mix. Since executionEngine will be an async call in most cases it is called afterwards to keep
    63→  // the state transition sync
    64→  //
    65→  // Equivalent to `assert executionEngine.notifyNewPayload(payload)`
    66→  if (isExecutionPayload(payload)) {
    67→    switch (externalData.executionPayloadStatus) {
    68→      case ExecutionPayloadStatus.preMerge:
    69→        throw Error("executionPayloadStatus preMerge");
    70→      case ExecutionPayloadStatus.invalid:
    71→        throw Error("Invalid execution payload");
    72→      case ExecutionPayloadStatus.valid:
    73→        break; // ok
    74→    }
    75→  }
    76→
    77→  const payloadHeader = isExecutionPayload(payload) ? executionPayloadToPayloadHeader(fork, payload) : payload;
    78→
    79→  // TODO Deneb: Types are not happy by default. Since it's a generic type going through ViewDU
    80→  // transformation then into all forks compatible probably some weird intersection incompatibility happens
